Route Decorators:
from flask import Flask, request, url_for, redirect, abort, jsonify

app = Flask(__name__)

# Basic routes
@app.route('/')
def index():
    return '<h1>Home Page</h1>'

@app.route('/about')
def about():
    return '<h1>About Us</h1>'

# Dynamic routes
@app.route('/user/<username>')
def profile(username):
    return f'<h1>Profile: {username}</h1>'

@app.route('/post/<int:post_id>')
def show_post(post_id):
    return f'<h1>Post #{post_id}</h1>'

@app.route('/path/<path:subpath>')
def show_subpath(subpath):
    return f'<h1>Subpath: {subpath}</h1>'

# HTTP methods
@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']
        # validate credentials
        return redirect(url_for('profile', username=username))
    return '''
        <form method="post">
            <input name="username">
            <input type="password" name="password">
            <button type="submit">Login</button>
        </form>
    '''

# url_for examples
# url_for('profile', username='alice') -> /user/alice
# url_for('static', filename='css/style.css') -> /static/css/style.css

